public class IconDetector extends Detector implements ResourceFolderScanner {
    private static final String NINE_PATCH = ".9.png";
    private Map<String, File> mNames;
    private Map<String, File> m9Names;
    ...
    @Override
    public void beforeCheckEachProject(@NonNull Context context) {
        mNames = new HashMap<>();
        m9Names = new HashMap<>();
    }
    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE;
    }
    @Override
    public void checkFolder(@NonNull ResourceContext context, @NonNull String folderName) {
        File folder = context.file;
        File[] files = folder.listFiles();
        if (files != null) {
            for (File file : files) {
                String name = file.getName();
                if (name.endsWith(DOT_PNG) || name.endsWith(DOT_9PNG)) {
                    String base = name.substring(0, name.lastIndexOf('.'));
                    if (name.endsWith(DOT_9PNG)) {
                        base = base.substring(0, base.lastIndexOf('.'));
                        m9Names.put(base, file);
                    } else {
                        mNames.put(base, file);
                    }
                }
            }
        }
    }
    @Override
    public void afterCheckEachProject(@NonNull Context context) {
        for (Map.Entry<String, File> entry : m9Names.entrySet()) {
            String base = entry.getKey();
            File ninePatch = entry.getValue();
            File regular = mNames.get(base);
            if (regular != null) {
                String message = String.format(
                    "The `%1$s` and `%2$s` both map to the same drawable resource `@drawable/%3$s`",
                    ninePatch.getName(), regular.getName(), base);
                context.report(ICON_MIXED_NINE_PATCH, regular, Location.create(regular), message);
                context.report(ICON_MIXED_NINE_PATCH, ninePatch, Location.create(ninePatch), message);
            }
        }
    }
}
```
